require_once __DIR__.'/../config/bootstrap.php';require_admin();$rows=db()->query("SELECT p.id,p.name,p.sku,p.is_active,COUNT(v.id) variants,MIN(v.price) price FROM products p LEFT JOIN product_variants v ON v.product_id=p.id GROUP BY p.id ORDER BY p.id DESC")->fetchAll();$pageTitle='Products — Ikki';require __DIR__.'/../includes/header.php';?>
<div class="admin-shell"><h1 class="page-title">Products</h1><nav class="admin-nav"><a href="/admin/">Overview</a><a href="/admin/products.php">Products</a><a href="/admin/orders.php">Orders</a><a href="/admin/logout.php">Sign out</a></nav><p class="muted">Product creation and editing interface is the next CMS module. Products can currently be loaded through the database.</p><table class="cart-table"><thead><tr><th>Name</th><th>SKU</th><th>Variants</th><th>From</th><th>Published</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['sku'])?></td><td><?=(int)$r['variants']?></td><td><?=$r['price']!==null?money($r['price']):'—'?></td><td><?=(int)$r['is_active']?'Yes':'Draft'?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>
